"""Generate fixtures."""

import os
import json
import mpmath
from mpmath import mp

# Set precision:
mp.dps = 80

# Get the file path:
FILE = os.path.realpath(__file__)

# Extract the directory in which this file resides:
DIR = os.path.dirname(FILE)

# Constant sqrt(2/pi):
SQRT_TWO_DIVIDED_BY_PI = mp.sqrt(mp.mpf(2) / mp.pi)


def to_float64(val_mp):
    """Convert mpmath number to float64 with exact IEEE 754 rounding.

    # Arguments

    * `val_mp`: mpmath number

    # Returns

    * `float`: double-precision float
    """
    if val_mp == 0 or mpmath.isnan(val_mp):
        return float(val_mp)
    return float(mp.nstr(val_mp, n=80))


def eval_gelu(x):
    """Evaluate exact GELU formula."""
    if x == 0.0:
        return 0.0
    x_mp = mp.mpf(x)
    val = mp.mpf('0.5') * x_mp * mp.erfc(-x_mp / mp.sqrt(2))
    return to_float64(val)


def eval_tanh(x):
    """Evaluate GELU tanh approximation formula."""
    if x == 0.0:
        return 0.0
    x_mp = mp.mpf(x)
    z_mp = SQRT_TWO_DIVIDED_BY_PI * (x_mp + mp.mpf('0.044715') * (x_mp**3))
    val = x_mp / (mp.mpf(1) + mp.exp(-2 * z_mp))
    return to_float64(val)


def eval_quick(x):
    """Evaluate GELU quick approximation formula."""
    if x == 0.0:
        return 0.0
    x_mp = mp.mpf(x)
    val = x_mp / (mp.mpf(1) + mp.exp(-mp.mpf('1.702') * x_mp))
    return to_float64(val)


def gen(x, eval_fn, name):
    """Generate fixture data and write to file.

    # Arguments

    * `x`: domain
    * `eval_fn`: function to evaluate
    * `name::str`: output filename
    """
    data = {
        "x": list(x),
        "expected": [eval_fn(v) for v in x]
    }
    filepath = os.path.join(DIR, name)
    with open(filepath, "w", encoding="utf-8", newline="\n") as outfile:
        json.dump(data, outfile)
        outfile.write("\n")


def main():
    """Generate fixture data."""
    # Exact GELU:
    x = [round(float(v), 4) for v in mpmath.linspace(-1.0, 1.0, 101)]
    gen(x, eval_gelu, "gelu_near_zero.json")

    x = [round(float(v), 4) for v in mpmath.linspace(-5.0, 5.0, 201)]
    gen(x, eval_gelu, "gelu_medium.json")

    x = [round(float(v), 2) for v in mpmath.linspace(5.0, 50.0, 91)]
    gen(x, eval_gelu, "gelu_large_positive.json")

    x = [round(float(v), 2) for v in mpmath.linspace(-35.0, -5.0, 121)]
    gen(x, eval_gelu, "gelu_large_negative.json")

    x = [round(float(v), 4) for v in mpmath.linspace(-37.60, -38.60, 81)]
    gen(x, eval_gelu, "gelu_subnormal.json")

    x = [-40.0, -39.0, -38.6, -2.0, -1.0, 0.0, 1.0, 2.0, 10.0, 50.0]
    gen(x, eval_gelu, "gelu_special.json")

    # Tanh approximation:
    x = [round(float(v), 4) for v in mpmath.linspace(-1.0, 1.0, 101)]
    gen(x, eval_tanh, "tanh_near_zero.json")

    x = [round(float(v), 4) for v in mpmath.linspace(-5.0, 5.0, 201)]
    gen(x, eval_tanh, "tanh_medium.json")

    x = [round(float(v), 2) for v in mpmath.linspace(5.0, 50.0, 91)]
    gen(x, eval_tanh, "tanh_large_positive.json")

    x = [round(float(v), 2) for v in mpmath.linspace(-20.0, -5.0, 121)]
    gen(x, eval_tanh, "tanh_large_negative.json")

    x = [-50.0, -25.0, -22.0, -2.0, -1.0, 0.0, 1.0, 2.0, 10.0, 50.0]
    gen(x, eval_tanh, "tanh_special.json")

    # Quick approximation:
    x = [round(float(v), 4) for v in mpmath.linspace(-1.0, 1.0, 101)]
    gen(x, eval_quick, "quick_near_zero.json")

    x = [round(float(v), 4) for v in mpmath.linspace(-5.0, 5.0, 201)]
    gen(x, eval_quick, "quick_medium.json")

    x = [round(float(v), 2) for v in mpmath.linspace(5.0, 50.0, 91)]
    gen(x, eval_quick, "quick_large_positive.json")

    x = [round(float(v), 2) for v in mpmath.linspace(-400.0, -5.0, 159)]
    gen(x, eval_quick, "quick_large_negative.json")

    x = [-500.0, -450.0, -442.0, -2.0, -1.0, 0.0, 1.0, 2.0, 10.0, 50.0]
    gen(x, eval_quick, "quick_special.json")


if __name__ == "__main__":
    main()
